-- REVERSA de 202610211600_oficina_segundo_cerebro_plantillas.sql · restaura el contenido EXACTO de las tres plantillas en version 3 (tomado de la base viva el 21-oct, respaldo en raw/backups/2026-10-21-oficina-tipos-vivos-antes-segundo-cerebro/) y las deja en version 5.
-- Mismas guardas: se niega con encargos en vuelo y exige version = 4.
BEGIN;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.oficina_encargos WHERE estado IN ('abierto', 'en_paso')) THEN
    RAISE EXCEPTION 'hay encargos de la oficina en vuelo: no se cambia la plantilla a mitad de un encargo';
  END IF;
END $$;

